import React, { useState, useRef } from "https://esm.sh/react";
import { createRoot } from "https://esm.sh/react-dom/client";
import styled from "https://esm.sh/@emotion/styled";
import { css, Global } from 'https://esm.sh/@emotion/react';

const timelineData = [
    {
        date: "1914",
        datetime: "1914",
        title: "Archduke's Assassination & War Declaration",
        content: [
            "Assassination of Archduke Franz Ferdinand of Austria.",
            "Germany declares war on France, Belgium does not allow German arms through to the French border."
        ]
    },
    {
        date: "Dec 25, 1915",
        datetime: "1915-12-25",
        title: "Zeppelin Raids & New Fronts Open",
        content: [
            "First Zeppelin raid on Great Britain.",
            "Italy declares war on Austria-Hungary.",
            "Kosovo Offensive, a phase of the Central Powers invasion of Serbia."
        ]
    },
    {
        date: "1916",
        datetime: "1916",
        title: "Gallipoli Campaign Ends & Key Battles",
        content: [
            "The Gallipoli Campaign ends in an Allied defeat and an Ottoman victory.",
            "Battle of Dobrich, a phase of the conquest of Romania.",
            "Allies capture Yanbu."
        ]
    },
    {
        date: "1917",
        datetime: "1917",
        title: "Major Raids & Political Shifts in Europe",
        content: [
            "British raid the Ancre.",
            "France: Paul Painlevé is replaced by Georges Clemenceau as Prime Minister.",
            "Russia signs an armistice with Germany."
        ]
    },
    {
        date: "1918",
        datetime: "1918",
        title: "Wilson's Fourteen Points & Eastern Front Offensive",
        content: [
            "Woodrow Wilson outlines his Fourteen Points.",
            "Operation Faustschlag, last offensive on Eastern Front.",
            "Yugoslav independence proclaimed."
        ]
    },
    {
        date: "1919",
        datetime: "1919",
        title: "Treaty of Versailles & The Peace Conference",
        content: [
            "Fakhri Pasha surrenders at Medina.",
            "Treaty of Versailles between the Allies and Germany: the Peace Conference opens in Paris.",
            "The UK ratifies the Treaty of Versailles."
        ]
    }
];

/**
 * A utility component for accessibility.
 * It visually hides content but keeps it available for screen readers.
 */
const VisuallyHidden = styled.span`
	border: 0;
	clip: rect(0, 0, 0, 0);
	height: 1px;
	margin: -1px;
	overflow: hidden;
	padding: 0;
	position: absolute;
	width: 1px;
`;

/**
 * The main container for the timeline, styled as an Ordered List (<ol>).
 * It uses CSS Grid to create two columns: one for the date and one for the content.
 * `grid-template-columns: max-content 1fr;` creates a narrow first column that fits its content (the date)
 * and a second column that takes up the remaining space.
 */
const TimelineList = styled.ol`
	display: grid; 
	gap: 2rem; /* Creates a gap between each timeline item */
	grid-template-columns: max-content 1fr;
	list-style: none;
	margin: 0;
	padding: 0;
`;

/**
 * The main content block for a timeline item, styled as an <article>.
 * It is explicitly placed in the second grid column.
 * The `::after` pseudo-element creates the circular dot on the timeline.
 */
const TimelineArticle = styled.article`
    grid-column: 2; /* Place this in the second column of the parent grid */
    position: relative; /* Required for positioning the pseudo-elements */

    /* This pseudo-element creates the blue dot for each timeline item */
    &::after {
		background-color: #3b82f6; 
		border-radius: 50%;
		content: '';
		height: 1rem;
		/* Position the dot in the middle of the 3rem gap created by TimelineItemLi */
		left: calc(-1.5rem); 
		position: absolute;
		top: 0.5rem; /* Vertically align the dot with the text */
		transform: translateX(-50%); /* Center the dot precisely on its horizontal axis */
		width: 1rem;
		z-index: 1; /* Ensure the dot appears on top of the vertical line */
    }
`;

/**
 * Represents a single list item (<li>) in the timeline.
 * It uses CSS subgrid to align its children (the date and the article) with the parent's (TimelineList) grid tracks.
 * `grid-column: 1 / -1;` makes this list item span the full width of the grid.
 * The `::before` pseudo-element on the nested article creates the vertical line connecting the dots.
 */
const TimelineItemLi = styled.li`
	display: grid;
	gap: 0 3rem; /* 3rem column gap between date and content */
	grid-column: 1 / -1; /* Make the list item span all columns of the parent grid */
	grid-template-columns: subgrid; /* Children will align with the parent's grid columns */

    /* This targets the <article> inside every list item EXCEPT the last one */
    &:not(:last-of-type) article::before {
		background-color: #d1d5db; /* Grey color for the connecting line */
		bottom: -2rem; /* Extend the line into the gap below the item */
		content: '';
		/* Position the line in the middle of the 3rem gap */
		left: calc(-1.5rem); 
		position: absolute;
		top: 2rem; /* Start the line below the dot */
		transform: translateX(-50%); /* Center the line perfectly */
		width: 3px;
	}
`;

/**
 * A styled div for displaying the date.
 * It is explicitly placed in the first grid column.
 */
const TimelineDateDiv = styled.div`
	color: #6b7280;
	grid-column: 1; 
	font-size: 2rem;
	font-weight: 200;
	text-align: right;
    transform: translateY(-0.6rem); /* Fine-tune vertical alignment */
`;

/**
 * A styled header for the timeline item's content.
 */
const ContentHeader = styled.header`
    h3 {
		color: #111827;
		font-size: 1.25rem;
		font-weight: 600;
		margin: 0 0 0.5rem 0;
    }
`;

/**
 * A styled div for the body/paragraph content of a timeline item.
 */
const ContentDiv = styled.div`
    p {
		margin: 0 0 0.75rem 0;

		&:last-child {
			margin-bottom: 0;
		}
	}
`;

/**
 * A React component that uses Emotion's <Global> component to inject
 * base styles for the entire page (e.g., body font, background color).
 */
const GlobalStyles = () => (
  <Global
    styles={css`
      body {
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
        line-height: 1.6;
        background-color: #f0f2f5;
        color: #333;
        padding: 2rem;
      }
    `}
  />
);

/**
 * Component for a single timeline event.
 * It receives props for the date, title, and content.
 * `children` will be the paragraphs of content passed to it.
 */
const TimelineItem = ({ date, datetime, title, children }) => (
    <TimelineItemLi>
        {/* The date is visually displayed here but hidden from screen readers to avoid repetition. */}
        <TimelineDateDiv aria-hidden="true">{ date }</TimelineDateDiv>
        <TimelineArticle>
            <ContentHeader>
                <h3>
                    {/* For accessibility, a semantic <time> element is provided for screen readers. */}
                    <VisuallyHidden as='time' dateTime={ datetime }>
                        { date }: 
                    </VisuallyHidden>
                    {/* The visible title of the event. */}
                    { title }
                </h3>
            </ContentHeader>
            <ContentDiv>
                { children }
            </ContentDiv>
        </TimelineArticle>
    </TimelineItemLi>
);

/**
 * The main Timeline component that wraps all the items.
 * The `reversed` attribute on the <ol> is semantically correct for a descending timeline.
 * It uses a compound component pattern by attaching `Timeline.Item`.
 */
const Timeline = ({ children }) => (
	<TimelineList reversed>
		{ children }
	</TimelineList>
);

// This creates a compound component, allowing for a clean API: <Timeline.Item>
Timeline.Item = TimelineItem;

/**
 * The main application component.
 */
function App(): JSX.Element {
	return (
		<>
            {/* Inject global styles for the page */}
			<GlobalStyles />
		    <section aria-labelledby="timeline-heading">
                {/* Provide a clear, accessible heading for the entire timeline section. */}
				<VisuallyHidden as='h2' id="timeline-heading">
					Historical Timeline
				</VisuallyHidden>

                {/* Render the main Timeline component */}
				<Timeline>
                    {/* Map over the static data to dynamically create a Timeline.Item for each event */}
		            {timelineData.map(({ date, datetime, title, content }, index) => (
						<Timeline.Item key={ index } date={ date } datetime={ datetime } title={ title }>
							{/* Map over the content array to create a <p> tag for each line */}
                            { content.map((p, i) => <p key={i}>{p}</p>) }
						</Timeline.Item>
					))}
				</Timeline>
			</section>
		</>
	);
}

const root = createRoot(document.getElementById("app"));
root.render(<App />);
export default App;
